import React, { useState } from "react";
import axios from "axios";
import { useNavigate } from "react-router-dom";

const Interview = ({ setInterviewDone }) => {
  const [video, setVideo] = useState(null);
  const [uploading, setUploading] = useState(false);
  const [message, setMessage] = useState("");
  const navigate = useNavigate();

  const handleFileChange = (e) => setVideo(e.target.files[0]);

  const handleUpload = async () => {
    if (!video) {
      setMessage("Please select a video first!");
      return;
    }

    const formData = new FormData();
    formData.append("file", video);

    try {
      setUploading(true);
      await axios.post("http://localhost:8080/api/video/upload", formData, {
        headers: { "Content-Type": "multipart/form-data" },
      });
      setMessage("✅ Video uploaded successfully!");
      setInterviewDone(true);
      setTimeout(() => navigate("/feedback"), 1500);
    } catch (err) {
      setMessage("❌ Upload failed!");
      console.error(err);
    } finally {
      setUploading(false);
    }
  };

  return (
    <div className="flex flex-col items-center justify-center min-h-[70vh] p-6 text-center">
      <h1 className="text-3xl font-bold mb-4">Upload Your Interview Video</h1>
      <input type="file" accept="video/*" onChange={handleFileChange} className="mb-4" />
      <button
        onClick={handleUpload}
        disabled={uploading}
        className="bg-blue-600 text-white px-6 py-2 rounded-md hover:bg-blue-700 transition"
      >
        {uploading ? "Uploading..." : "Upload Video"}
      </button>
      {message && <p className="mt-4 text-lg">{message}</p>}
    </div>
  );
};

export default Interview;
